#!/bin/bash
sed -i 's/Sliders,/Sliders,\n  Skull,/g' src/components/Sidebar.tsx
sed -i '/<button\s*id="open-settings-btn"/i \            <button\n              id="panic-wipe-btn"\n              type="button"\n              onClick={() => { if(window.confirm("FATAL WARNING: Erase all traces, chats, and self-destruct local session?")) { localStorage.clear(); sessionStorage.clear(); window.location.reload(); } }}\n              className="flex items-center gap-1.5 px-2 py-1.5 rounded-md text-xs font-bold text-red-600 dark:text-red-500 hover:bg-red-500/10 transition-colors"\n              title="Anti-Forensics Panic Wipe"\n            >\n              <Skull className="w-4 h-4 animate-pulse" />\n              <span>Zero Trace</span>\n            </button>' src/components/Sidebar.tsx
